"""Shared read-only catalogue. Update JSON in data/; not code in the API."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent.parent
DATA=ROOT/'data'
def load(name):
    return json.loads((DATA/name).read_text(encoding='utf8'))
SKILLS=load('skills.json')
SKILL_INDEX={s['id']:s for s in SKILLS}
ROLES=load('roles.json')
PLACEHOLDER_RESOURCES=load('learning_resources.json')
# Checked courses: courses.json is imported from LaluanKu (checked 2026-10-20; regenerated by scripts/import_laluanku_seed.py),
# extra_courses.json is maintained by hand (each entry records the date its provider page was checked).
COURSES=load('courses.json')+load('extra_courses.json')
COST_LABEL={'free':'Free','low':'Low cost (paid certificate)','hrdc_claimable':'HRD Corp claimable (confirm per run)'}
def _course_resources():
    rows=[{'id':c['id'],'title':c['title'],'provider':c['provider'],'url':c['url'],'skill_id':sid,'level':None,'hours':c['hours'],
           'duration':f"{c['hours']:g} h"+(' (estimated)' if c['hours_estimated'] else ''),'cost':COST_LABEL.get(c['cost'],c['cost']),
           'verification_status':('provider page checked '+c['checked']) if c.get('checked') else 'source catalogue snapshot checked 2026-10-20',
           'notes':c['notes']} for c in COURSES for sid in c['skill_ids']]
    return sorted(rows,key=lambda r:(list(COST_LABEL.values()).index(r['cost']) if r['cost'] in COST_LABEL.values() else 9,r['hours']))
# Pathway resources: checked courses first; placeholders only for skills no checked course teaches.
_covered={r['skill_id'] for r in _course_resources()}
RESOURCES=_course_resources()+[r for r in PLACEHOLDER_RESOURCES if r['skill_id'] not in _covered]
